    if verify_hash is not None and hex_hash == verify_hash:
        return hex_hash, True
    return hex_hash, None

import numpy as np
from scipy.stats import norm

def task_func(data: np.ndarray, threshold: float = 2.0) -> list:
    if data.size == 0:
        return [], np.nan, np.nan
    mean = np.mean(data)
    std = np.std(data)
    if std == 0:
        return [], mean, std
    z_scores = (data - mean) / std
    outliers = np.where(np.abs(z_scores) > threshold)[0].tolist()
    return outliers, mean, np.var(data)

