import numpy as np
import random

def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    length = random.randint(MIN_WORDS, MAX_WORDS)
    words = random.choices(WORDS_POOL, k=length)
    if length % 2 == 0:
        half = length // 2
        words = words[:half] + words[:half][::-1]
    else:
        half = length // 2
        words = words[:half] + [words[half]] + words[:half][::-1]
    return ' '.join(words)

