import pandas as pd

def task_func(l, n_groups = 5):
    shuffle(l)
    series = []
    for item in l:
        for _ in range(n_groups):
            if len(item) > 0:
                move = randint(1, min(len(item), 3))
                item = item[move:] + item[:move]
        series.append(item)
    return pd.Series(series)
